export const SITEMAP_START = START;

const VERMERK_DE = Object.freeze({
  stand: "2026-10-03",
  grundlage: "Seite rendert eine eigene Fassung für Deutschland (16 Bundesländer zuerst, Landesrecht DE); Inhalte aus Welle 1",
  pruefer: "TODO-E6",
});

const VERMERK_AT = Object.freeze({
  stand: "2026-10-03",
  grundlage: "Seite rendert eine eigene Fassung für Österreich (Recht AT, Begriffe, ohne ungeprüfte Pachtwerte); fachlich überarbeitet in Welle 1",
  pruefer: "TODO-E6",
});

const VERMERK_CH = Object.freeze({
  stand: "2026-10-04",
  grundlage: "Seite rendert eine eigene Fassung für die Schweiz (RPG Art. 24ter, Bewilligung Gemeinde/Kanton, HEIV, LEG/vZEV; ohne ungeprüfte Pacht- und Kostenwerte); Quellen in src/data/laender/ch/ und src/data/regionen/schweiz.js",
  pruefer: "TODO-E6",
});

/**
 * Echter Länderinhalt je Land (Muster-Schlüssel → Freigabe-Vermerk).
 * Nur eintragen, wenn die Seite für das Land WIRKLICH anderen, geprüften Inhalt rendert
 * (über inhaltFuer()/landDerAnfrage(), src/lib/land/inhalte.js) – nicht nur dieselbe Seite
 * mit anderem Präfix.
 */
export const LAENDERINHALT = Object.freeze({
  DE: Object.freeze({
    "/regionen": VERMERK_DE,
  }),
  AT: Object.freeze({
    "/flaechencheck": VERMERK_AT,
    "/energiegemeinschaften": VERMERK_AT,
    "/regionen": VERMERK_AT,
  }),
  CH: Object.freeze({
    "/freiflaeche": VERMERK_CH,
    "/energiegemeinschaften": VERMERK_CH,
    "/agri-pv": VERMERK_CH,
  }),
});

/** Regionsseiten: Land je Slug aus den Stammdaten der Regionen. */
export const REGION_LAND = Object.freeze(Object.fromEntries(REGIONEN_META.map((r) => [r.slug, r.land])));

/** Schlüssel einer Regionsseite ("tirol" → "/regionen/tirol"). */
export const regionSchluessel = (slug) => "/regionen/" + slug;

const MUSTER = Object.keys(SEITEN)
  .filter((k) => SEITEN[k].dynamisch)
  .map((k) => ({ k, basis: k.slice(0, k.indexOf("/[")) }));

/**
 * Pfad ohne Präfix → Registereintrag. Dynamische Seiten (/regionen/tirol) werden auf ihr Muster
 * ("/regionen/[slug]") abgebildet; Regionen nur mit bekanntem Slug.
 * @returns {{ schluessel: string, muster: string, eintrag: object } | null}
 */
export function seiteFuer(schluesselRoh) {
  if (typeof schluesselRoh !== "string") return null;
  const schluessel = nurPfad(schluesselRoh);
  if (Object.hasOwn(SEITEN, schluessel) && !SEITEN[schluessel].dynamisch) return { schluessel, muster: schluessel, eintrag: SEITEN[schluessel] };
  for (const { k, basis } of MUSTER) {
    if (!schluessel.startsWith(`${basis}/`)) continue;
    const slug = schluessel.slice(basis.length + 1);
    if (!/^[a-z0-9-]+$/.test(slug)) continue;
    if (k === "/regionen/[slug]" && !Object.hasOwn(REGION_LAND, slug)) continue;
    return { schluessel, muster: k, eintrag: SEITEN[k] };
  }
  return null;
}

/** Hat dieser präfixlose Pfad eine Länderfassung (/de…, /at…, /ch…)? */
export const hatLandfassung = (schluessel) => !!seiteFuer(schluessel);

/** Gibt es für die Seite im Land echten, freigegebenen Länderinhalt? */
export function eigenerInhalt(schluessel, land) {
  const s = seiteFuer(schluessel);
  if (!s || !LAND_CODES.includes(land)) return false;
  return Object.hasOwn(LAENDERINHALT[land], s.muster);
}

/** Länder mit eigenem Inhalt für eine Seite (LAND_CODES-Reihenfolge). */
export const laenderMitInhalt = (schluessel) => LAND_CODES.filter((l) => eigenerInhalt(schluessel, l));

/**
 * Indexierbar? land null = gemeinsame Seite (indexiert, außer index: false);
 * Länderfassung nur mit eigenem Inhalt (sonst noindex bis zur Freigabe).
 */
export function indexierbar(schluessel, land = null) {
  const s = seiteFuer(schluessel);
  if (!s || s.eintrag.index === false) return false;
  return land ? eigenerInhalt(schluessel, land) : true;
}

/** Alle konkreten Schlüssel (Regionen aufgelöst; Ratgeber und Exposés nicht). */
export function alleSchluessel() {
  const liste = [];
  for (const k of Object.keys(SEITEN)) {
    if (k === "/regionen/[slug]") liste.push(...Object.keys(REGION_LAND).map(regionSchluessel));
    else if (!SEITEN[k].dynamisch) liste.push(k);
  }
  return liste;
}
// src/lib/land/inhalte.js – Schnittstelle für Länderinhalte (für die Inhalts-Teams)
//
// Grundsatz: Eine Seite, ein Design. Länder unterscheiden sich nur in Texten, Werten und
// Bausteinen – nie in Layout oder Komponenten.
//
// 1) Land der Seite holen
//    Server-Seite:      const land = await seitenLand(params);        // src/lib/land/seite.js
//    Server-Baustein:   const land = landDerAnfrage();                // nach seitenLand() der Seite
//    Client-Baustein:   const { land } = useLand();                   // src/components/Land/useLand.js
//    land ist "DE" | "AT" | "CH" oder null (= gemeinsame Seite ohne Länderwahl).
//
// 2) Texte und Werte je Land
//    const TEXTE = {
//      gemeinsam: { titel: "Solarparks in DACH", lead: "…" },   // Pflicht: Stand wie vor Welle 2
//      AT: { lead: "… nach EAG und Landesraumordnung …" },        // nur, was in AT anders ist
//      CH: { lead: "… nach RPG Art. 24ter …" },
//    };
//    const t = inhaltFuer(TEXTE, land);   // AT: { titel aus gemeinsam, lead aus AT }
//    Fehlt ein Land, gilt „gemeinsam“. DE ohne eigenen Eintrag = gemeinsam.
//
// 3) Zahlen nur, wo sie für das Land geprüft sind
//    const modus = zahlenModus(land, ["DE"]);   // Länder, deren Werte an der Quelle geprüft sind
//      "zeigen"    → Werte normal anzeigen (Land ist geprüft)
//      "gemeinsam" → Werte anzeigen und dezent „gilt für Deutschland“ dazu (<GiltFuer />)
//      "hinweis"   → KEINE Werte, stattdessen <LandHinweis land={land} /> („… werden geprüft – Ergebnis auf Anfrage“)
//    Fertiger Baustein: <LandWerte land={land} geprueft={["DE"]}>…Werte…</LandWerte>
//    (src/components/Land/LandHinweis.js)
//
// 4) Rechner bekommen das Land automatisch: RechnerSeite liest landDerAnfrage(), die Rechner
//    useLand(); Startwerte über landStart() (src/components/Land/useLand.js). Für AT/CH greift
//    die Länder-Sperre der Länder-Engine (src/lib/invest/laender/sperre.js, marktFuer()).
//
// 5) Freigabe für Suchmaschinen: Erst wenn eine Seite für ein Land echten, geprüften Inhalt
//    rendert, den Eintrag in LAENDERINHALT (src/lib/land/seiten.js) mit Vermerk ergänzen. Dann
//    bekommt die Länderfassung index, eigenes canonical, hreflang und einen Sitemap-Eintrag.
//    Vorher bleibt sie noindex – sie ist trotzdem erreichbar und sieht gleich aus.

import { LAENDER, landCode } from "./laender.js";

const istObjekt = (x) => x !== null && typeof x === "object" && !Array.isArray(x) && !(x && x.$$typeof);

/**
 * Inhalt für ein Land mit Rückfall auf „gemeinsam“.
 * Objekte werden flach zusammengeführt (Land überschreibt gemeinsam), alles andere ersetzt.
 * @template T
 * @param {{ gemeinsam: T, DE?: Partial<T>|T, AT?: Partial<T>|T, CH?: Partial<T>|T }} inhalte
 * @param {string|null} land
 * @returns {T}
 */
export function inhaltFuer(inhalte, land) {
  if (!inhalte || !Object.hasOwn(inhalte, "gemeinsam")) throw new Error("inhaltFuer: Eintrag „gemeinsam“ fehlt");
  const l = landCode(land);
  const basis = inhalte.gemeinsam;
  if (!l || !Object.hasOwn(inhalte, l) || inhalte[l] === undefined) return basis;
  const eigen = inhalte[l];
  return istObjekt(basis) && istObjekt(eigen) ? { ...basis, ...eigen } : eigen;
}

/**
 * Wie Zahlenwerte im Land angezeigt werden.
 * @param {string|null} land
 * @param {string[]} geprueft Länder, deren Werte an der Originalquelle geprüft sind (Standard: nur DE)
 * @returns {"zeigen"|"gemeinsam"|"hinweis"}
 */
export function zahlenModus(land, geprueft = ["DE"]) {
  const l = landCode(land);
  if (!l) return "gemeinsam";
  return geprueft.includes(l) ? "zeigen" : "hinweis";
}

/** Text des Länderhinweises („Rechenwerte für die Schweiz werden geprüft – Ergebnis auf Anfrage“). */
export function landHinweisText(land, thema = "Rechenwerte") {
  const l = landCode(land) || "DE";
  return `${thema} ${LAENDER[l].fuerLand} werden geprüft – Ergebnis auf Anfrage`;
}

/** Englischer Länderhinweis („Figures for Switzerland are being reviewed – result on request“). */
export function landHinweisTextEn(land, thema = "Figures") {
  const l = landCode(land) || "DE";
  return `${thema} ${LAENDER[l].en.fuerLand} are being reviewed – result on request`;
}

// src/lib/sprache/seiten.js – Register der übersetzten Seiten (Sprachmodell)
//
// Jede öffentliche Seite aus dem Register src/lib/land/seiten.js gibt es auch auf Englisch unter
// /en/<pfad> und /en/<land>/<pfad> – mit DERSELBEN Seitenkomponente (Routen erzeugt mit
// scripts/landfassungen.mjs). Solange eine Seite nicht übersetzt ist, zeigt sie den deutschen
// Text mit dem dezenten Hinweis „not yet available in English“ und trägt noindex.
//
// UEBERSETZT: Seiten, deren Inhalt vollständig englisch rendert (Wörterbuch der Seite fertig,
//   Rahmen ohnehin englisch). Nur diese englischen Fassungen werden indexiert, bekommen ein
//   eigenes canonical, stehen im hreflang-Cluster ("en") und in der Sitemap.
//   Eintragen erst, wenn die Seite unter /en/<pfad> bei 1440 und 390 geprüft ist.
//
// EN_LAENDERINHALT: englische LÄNDERfassungen (/en/at/…) mit eigenem, übersetztem Länderinhalt.
//   Eintrag nur, wenn die Seite in LAENDERINHALT steht UND übersetzt ist (Gruppe 2: alle
//   Länderinhalte übersetzt). Ohne Eintrag zeigt die englische Länderfassung den deutschen
//   Länderinhalt (Rückfall in inhaltFuerSprache) und trägt noindex.
//
// Relative Importe mit Dateiendung (next.config.mjs, Middleware und node:test laden das Modul).

import { LAND_CODES } from "../land/laender.js";
import { LAENDERINHALT, seiteFuer } from "../land/seiten.js";

const VERMERK_EN = Object.freeze({
  stand: "2026-10-08",
  grundlage: "Seite und alle Bausteine über Wörterbücher übersetzt (src/lib/sprache/woerterbuch.js)",
  pruefer: "TODO-E6",
});

/** Übersetzer-Gruppe 1 (Börse, Investoren, Unternehmen, Recht) – je Seite bei 1440 und 390 geprüft. */
const VERMERK_EN_G1 = Object.freeze({
  stand: "2026-10-08",
  grundlage: "Seite und Bausteine über Wörterbücher übersetzt (Gruppe 1: Börse, Investoren, Unternehmen)",
  pruefer: "TODO-E6",
});

