  DE: Object.freeze({ "/regionen": VERMERK_EN_G2 }),
  AT: Object.freeze({ "/flaechencheck": VERMERK_EN_G2, "/energiegemeinschaften": VERMERK_EN_G2, "/regionen": VERMERK_EN_G2 }),
