 *
 *   const [e, setE] = useState(STANDARD);
 *   useTeilbarerZustand(e, (neu) => setE((a) => ({ ...a, ...neu })), {
 *     optionen: { profil: LASTPROFILE.map((p) => p.id) },
 *     grenzen: { laufzeit: [3, 20] },
