  try {
    buch = fn ? fn(eingaben) : null;
  } catch {
    buch = null; // Fallback unten
  }
  const register = (buch?.eintraege || []).map((x) => {
    if (x.fehlt) {
      return rechenlogikEintrag({ id: x.id, label: BEZEICHNUNG[x.id] || x.id, wert: "–", einheit: "" });
