    quellenRechenlogik: (QUELLEN || []).slice(0, 12).map((q) => ({ titel: q.titel || q.label || "", url: q.url || null })).filter((q) => q.titel),
    hinweis: buch ? "" : `${HINWEIS_RECHENLOGIK} (${STAND}) – das Faktenregister lieferte für diesen Rechner keine Einträge.`,
  };
}
