  ];
  return (
    <Rahmen>
      <article id="ov-bericht" lang="de" aria-labelledby="bericht-titel" data-bericht={bericht.rechner}>
        <header className="border-b border-ink-200 pb-7">
          <div className="flex flex-wrap items-center justify-between gap-3">
