import { createElement } from "react";

/** params (Promise oder Objekt) um sprache ergänzen. */
export const mitSprache = (params, sprache = "en") => Promise.resolve(params).then((p) => ({ ...(p || {}), sprache }));

/** Seitenkomponente in einer Sprache. */
